#!/usr/bin/env bash
# Generated by genproj — install the repository's git hooks and the scanner.
#
# `core.hooksPath` is a git setting, not a file in `.git/`: it has to be set
# once per clone. This script is idempotent, so post-create setup can run it on
# every container start.
#
# It FAILS LOUDLY when core.hooksPath does not end up as `.githooks`. The bug
# this replaces (`npx simple-git-hooks` in a repo with no package.json) exited
# successfully having installed nothing, and every commit since went unscanned.
set -euo pipefail

ROOT=$(git rev-parse --show-toplevel 2>/dev/null || pwd)
cd "$ROOT"

# Missing scanner is a warning, not a failure: the commit hook is fail-open by
# design, and CI's full-history scan is the gate that cannot be skipped. A
# post-create step that aborts offline would leave the devcontainer unusable.
if bash scripts/install-gitleaks.sh; then :; else
  echo "WARN: gitleaks could not be installed; the local scan will be skipped." >&2
  echo "WARN: CI's full-history scan is unaffected." >&2
fi

git config core.hooksPath .githooks

HOOKS_PATH=$(git config --get core.hooksPath || true)
if [ "$HOOKS_PATH" != ".githooks" ]; then
  echo "ERROR: core.hooksPath is '${HOOKS_PATH:-<unset>}', expected '.githooks'." >&2
  exit 1
fi

if [ ! -x .githooks/pre-commit ]; then
  echo "ERROR: .githooks/pre-commit is missing or not executable." >&2
  echo "ERROR: fix the file mode with: git update-index --chmod=+x .githooks/pre-commit" >&2
  exit 1
fi

echo "OK: git hooks installed (core.hooksPath=.githooks)."
